#!/usr/bin/env bash
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
template="$repo_root/tools/templates/cbp_pr71_active_good_dispatch_good.template.txt"
output="${1:-$repo_root/in_game/common/scripted_effects/cbp_zz_pr71_active_good_dispatch_generated.txt}"

# shellcheck source=tools/cbp_tool_lib.sh
source "$repo_root/tools/cbp_tool_lib.sh"
cbp_load_goods_registry
goods=("${cbp_goods[@]}")

mkdir -p "$(dirname "$output")"

{
	cat <<'TXT'
# Generated by tools/generate_pr71_active_good_dispatch_helpers.sh.
# Do not edit manually.
# Literal per-good PR7.1 active-good dispatch guards are generated from
# tools/templates/cbp_pr71_active_good_dispatch_good.template.txt.
#
# PR126 PR7.1 active-good dispatch guards.
#
# This file preserves PR7's promoted-market ownership shape while avoiding the
# expensive generated all-good helper body when the existing main-branch
# business gate says the good has no work.
#
# Important: the generated per-good symbol surface still exists because EU5
# scripted effect names and map names must remain literal. PR7.1 narrows the
# call into the heavy generated helpers; it does not remove the generated
# helpers from the repository.
#
# Q8.1 keeps those business guards live but gates the temporary PR7.1 metrics
# behind cbp_pr71_metrics_enabled_trigger. Normal gameplay still considers
# generated literal goods, but it no longer writes per-good debug/profile
# counters unless debug or audit mode enabled those metrics.
#
# Q8.2 aggregate pre-gating is deferred. The all-goods pre-scan can become an
# anti-optimisation when most country-market pairs have at least one pending
# demand. Keep the current PR7.1 per-good pending dispatcher until a later
# sparse pending-index implementation is proven.
#
# The live monthly handoff is intentionally not generated here. EU5 rejects
# duplicate scripted-effect keys, so the tracked PR7 live effect must call the
# generated PR7.1 dispatchers directly.

cbp_pr71_reset_active_good_metrics = {
	if = {
		limit = { cbp_pr71_metrics_enabled_trigger = yes }
		remove_global_variable = cbp_pr71_active_good_metrics_stamp
		remove_global_variable = cbp_pr71_us00_goods_considered
		remove_global_variable = cbp_pr71_us00_goods_processed
		remove_global_variable = cbp_pr71_us00_goods_produced_gate_hits
		remove_global_variable = cbp_pr71_us00_goods_previous_state_hits
		remove_global_variable = cbp_pr71_us10_goods_considered
		remove_global_variable = cbp_pr71_us10_requests_processed
		remove_global_variable = cbp_pr71_us10_pending_request_hits

		set_global_variable = { name = cbp_pr71_us00_goods_considered value = 0 }
		set_global_variable = { name = cbp_pr71_us00_goods_processed value = 0 }
		set_global_variable = { name = cbp_pr71_us00_goods_produced_gate_hits value = 0 }
		set_global_variable = { name = cbp_pr71_us00_goods_previous_state_hits value = 0 }
		set_global_variable = { name = cbp_pr71_us10_goods_considered value = 0 }
		set_global_variable = { name = cbp_pr71_us10_requests_processed value = 0 }
		set_global_variable = { name = cbp_pr71_us10_pending_request_hits value = 0 }
	}
}

cbp_pr71_prepare_active_good_metrics = {
	if = {
		limit = { cbp_pr71_metrics_enabled_trigger = yes }
		save_temporary_scope_value_as = {
			name = cbp_pr71_active_good_metrics_stamp
			value = {
				value = current_year
				multiply = 12
				add = current_month
			}
		}

		if = {
			limit = {
				OR = {
					NOT = { has_global_variable = cbp_pr71_active_good_metrics_stamp }
					global_var:cbp_pr71_active_good_metrics_stamp != scope:cbp_pr71_active_good_metrics_stamp
				}
			}
			cbp_pr71_reset_active_good_metrics = yes
			set_global_variable = { name = cbp_pr71_active_good_metrics_stamp value = scope:cbp_pr71_active_good_metrics_stamp }
		}
		else_if = {
			limit = { NOT = { has_global_variable = cbp_pr71_us00_goods_considered } }
			cbp_pr71_reset_active_good_metrics = yes
			set_global_variable = { name = cbp_pr71_active_good_metrics_stamp value = scope:cbp_pr71_active_good_metrics_stamp }
		}
	}
}

cbp_pr71_note_us00_goods_considered = {
	if = { limit = { cbp_pr71_metrics_enabled_trigger = yes } set_global_variable = { name = cbp_pr71_us00_goods_considered value = { value = global_var:cbp_pr71_us00_goods_considered add = 1 } } }
}

cbp_pr71_note_us00_goods_processed = {
	if = { limit = { cbp_pr71_metrics_enabled_trigger = yes } set_global_variable = { name = cbp_pr71_us00_goods_processed value = { value = global_var:cbp_pr71_us00_goods_processed add = 1 } } }
}

cbp_pr71_note_us00_goods_produced_gate_hit = {
	if = { limit = { cbp_pr71_metrics_enabled_trigger = yes } set_global_variable = { name = cbp_pr71_us00_goods_produced_gate_hits value = { value = global_var:cbp_pr71_us00_goods_produced_gate_hits add = 1 } } }
}

cbp_pr71_note_us00_goods_previous_state_hit = {
	if = { limit = { cbp_pr71_metrics_enabled_trigger = yes } set_global_variable = { name = cbp_pr71_us00_goods_previous_state_hits value = { value = global_var:cbp_pr71_us00_goods_previous_state_hits add = 1 } } }
}

cbp_pr71_note_us10_goods_considered = {
	if = { limit = { cbp_pr71_metrics_enabled_trigger = yes } set_global_variable = { name = cbp_pr71_us10_goods_considered value = { value = global_var:cbp_pr71_us10_goods_considered add = 1 } } }
}

cbp_pr71_note_us10_pending_request_hit = {
	if = { limit = { cbp_pr71_metrics_enabled_trigger = yes } set_global_variable = { name = cbp_pr71_us10_pending_request_hits value = { value = global_var:cbp_pr71_us10_pending_request_hits add = 1 } } }
}

cbp_pr71_note_us10_request_processed = {
	if = { limit = { cbp_pr71_metrics_enabled_trigger = yes } set_global_variable = { name = cbp_pr71_us10_requests_processed value = { value = global_var:cbp_pr71_us10_requests_processed add = 1 } } }
}

TXT

	for good in "${goods[@]}"; do
		cbp_render_template_to_stdout "$template" "GOOD=$good"
		printf '\n'
	done

	cat <<'TXT'
cbp_pr71_process_us00_monthly_market_active_goods = {
TXT
	for good in "${goods[@]}"; do
		printf '\tcbp_pr71_process_us00_monthly_market_good_%s = yes\n' "$good"
	done
	cat <<'TXT'
}

cbp_pr71_process_us10_monthly_market_pending_goods = {
TXT
	for good in "${goods[@]}"; do
		printf '\tcbp_pr71_process_us10_monthly_market_good_%s = yes\n' "$good"
	done
	cat <<'TXT'
}
TXT
} > "$output"

printf 'Generated %s\n' "$output"
